        ("Tinh tinh", "Loài linh trưởng thông minh nhất có ADN giống con người đến 98% và biết dùng cành cây làm công cụ?", "Tinh tinh", ["Khỉ đột", "Vượn cáo", "Khỉ đuôi sóc"], "Tinh tinh có trí tuệ vượt trội, biết dùng que chọc tổ mối và biểu lộ cảm xúc phong phú.", "8-9", 3, "MC", "Tinh tinh thông minh"),
        ("Gấu trúc (Panda)", "Loài gấu có khoang lông đen trắng ở Trung Quốc, thức ăn khoái khẩu là cành lá trúc tươi?", "Gấu trúc", ["Gấu ngựa", "Gấu chó", "Gấu xám"], "Gấu trúc dành tới 12 tiếng mỗi ngày để gặm nhấm thân và lá cây trúc, tre.", "6-7", 1, "MC", "Gấu trúc ăn trúc"),
        ("Gấu Bắc Cực", "Loài gấu lớn sống ở vùng băng tuyết giá lạnh, bơi lội giỏi và săn hải cẩu để sinh sống?", "Gấu Bắc Cực", ["Gấu nâu", "Gấu trúc", "Chim cánh cụt"], "Gấu Bắc Cực có lớp mỡ dày giữ ấm và bàn chân rộng có đệm lông để không bị trượt trên băng.", "7-8", 2, "MC", "Gấu trắng Bắc Cực"),
        ("Chó sói", "Loài thú ăn thịt họ chó thường hú vang dưới ánh trăng và săn mồi theo bầy đàn kỷ luật?", "Chó sói", ["Cáo đỏ", "Chó hoang", "Linh cẩu"], "Chó sói có tổ chức bầy đàn chặt chẽ, luôn có sói đầu đàn dẫn dắt đi săn.", "7-8", 2, "MC", "Sói hú đêm trăng"),
        ("Cáo đỏ", "Loài thú ăn thịt nhỏ có chiếc đuôi xù to đẹp mắt, nổi tiếng tinh ranh trong các câu chuyện ngụ ngôn?", "Con Cáo", ["Chồn hôi", "Chuột túi", "Nhím"], "Cáo có khứu giác thính nhạy, bước chân nhẹ nhàng và chiếc đuôi giúp giữ ấm cơ thể khi ngủ.", "6-7", 1, "MC", "Cáo tinh ranh"),
        ("Con Nhím", "Loài thú nhỏ nào có bộ lông biến thành hàng ngàn chiếc gai nhọn hoắt để tự vệ khi gặp nguy hiểm?", "Con Nhím", ["Tê tê", "Chuột chũi", "Lười"], "Khi bị tấn công, nhím cuộn tròn người lại thành một quả cầu gai sắc nhọn khiến kẻ thù khiếp sợ.", "6-7", 1, "MC", "Nhím xù lông gai"),
        ("Tê tê", "Loài thú ăn kiến đặc biệt nào có vảy cứng bao phủ toàn thân và cuộn tròn như quả bóng khi phòng vệ?", "Con Tê tê", ["Thằn lằn", "Kỳ đà", "Bò sát"], "Tê tê dùng móng vuốt đào tổ kiến và dùng lưỡi dài dính để bắt kiến, mối.", "7-8", 2, "MC", "Tê tê cuộn tròn"),
        ("Chuột túi (Kangaroo)", "Loài thú có túi đặc trưng của nước Úc, di chuyển bằng cách nhảy hai chân sau cực khỏe là gì?", "Kangaroo (Chuột túi)", ["Koala", "Gấu túi Wombat", "Đà điểu"], "Chuột túi mẹ có chiếc túi ấm áp trước bụng để nuôi dưỡng và bảo vệ chuột túi con.", "6-7", 1, "MC", "Kangaroo nước Úc"),
        ("Gấu túi Koala", "Loài thú có túi đáng yêu ở Úc ngủ tới 18-20 tiếng mỗi ngày và chỉ ăn lá cây bạch đàn (khuynh diệp)?", "Koala", ["Gấu lười", "Gấu trúc", "Sóc bay"], "Lá bạch đàn chứa ít năng lượng và có độc tố nhẹ nên Koala ngủ nhiều để tiêu hóa và tiết kiệm sức.", "7-8", 2, "MC", "Koala leo cây"),
        ("Con Lười", "Loài thú sống trên cây ở rừng nhiệt đới Nam Mỹ di chuyển cực kỳ chậm chạp đến mức rêu mọc trên lông?", "Con Lười", ["Con Vượn", "Con Cầy", "Chuột túi"], "Con lười di chuyển chậm để tiết kiệm năng lượng tối đa và tránh sự chú ý của đại bàng săn mồi.", "7-8", 2, "MC", "Con lười chậm chạp"),
        ("Hươu sao", "Loài thú ăn cỏ hiền lành có những đốm trắng tròn như sao trên lưng, con đực có gạc sừng phân nhánh?", "Hươu sao", ["Nai rừng", "Sơn dương", "Hoẵng"], "Gạc hươu rụng đi và mọc lại hàng năm, gạc non mới mọc được gọi là lộc nhung.", "7-8", 2, "MC", "Hươu sao đốm trắng"),
        ("Chồn hôi", "Loài thú nhỏ nào tự vệ bằng cách xịt ra một luồng chất lỏng có mùi hôi nồng nặc khiến kẻ thù bỏ chạy?", "Chồn hôi", ["Mèo rừng", "Chồn hương", "Chuột chũi"], "Tuyến mùi dưới đuôi của chồn hôi có thể bắn xa tới 3 mét với mùi khó chịu kéo dài nhiều ngày.", "7-8", 2, "MC", "Chồn hôi xịt mùi"),
        ("Sóc", "Loài gặm nhấm nhỏ có chiếc đuôi bông xù, leo trèo nhanh thoăn thoắt và thích ăn quả hạt dẻ?", "Con Sóc", ["Chuột đồng", "Nhím", "Chuột cống"], "Sóc thường vùi các loại hạt sồi, hạt dẻ dưới đất để dự trữ mùa đông, góp phần trồng rừng mới.", "6-7", 1, "MC", "Sóc chuyền cành"),
        ("Dơi", "Loài động vật có vú (đẻ con và nuôi con bằng sữa) duy nhất biết bay lượn thực sự trên bầu trời là gì?", "Con Dơi", ["Chim bồ câu", "Sóc bay", "Chuồn chuồn"], "Dơi đẻ con và cho con bú sữa mẹ, cánh của dơi là lớp màng da nối giữa các ngón tay dài.", "7-8", 2, "MC", "Dơi bay đêm"),
        ("Dơi bắt mồi", "Dơi bay và bắt mồi chuẩn xác trong đêm tối bằng cách nào mà không cần dùng mắt?", "Phát sóng siêu âm và nhận phản xạ (Định vị hồi âm)", ["Dùng mũi ngửi mùi gió", "Dùng đuôi cảm nhận nhiệt độ", "Dùng tai nghe tiếng gió"], "Dơi phát ra tiếng kêu tần số cao (siêu âm), sóng dội lại từ con mồi giúp dơi định vị chính xác.", "8-9", 3, "MC", "Định vị bằng siêu âm"),
        ("Chuột chũi", "Loài động vật nào sống hầu như cả đời dưới lòng đất, mắt gần như mù nhưng có móng vuốt đào bới siêu đẳng?", "Chuột chũi", ["Con Giun", "Thỏ rừng", "Dế trũi"], "Chuột chũi có khứu giác và xúc giác cực nhạy để săn giun và ấu trùng dưới lòng đất tối tăm.", "7-8", 2, "MC", "Chuột chũi đào đất"),
        ("Cầy hương", "Loài thú nhỏ nào ăn quả cà phê chín mọng, tạo nên loại cà phê chồn thơm ngon nức tiếng?", "Cầy hương (Chồn hương)", ["Khỉ", "Sóc", "Chuột"], "Enzym trong dạ dày cầy hương lên men hạt cà phê tự nhiên tạo nên hương vị đặc biệt hảo hạng.", "8-9", 3, "MC", "Cà phê chồn"),
        ("Linh cẩu", "Loài thú săn mồi thảo nguyên có tiếng kêu nghe như điệu cười kỳ quái và lực cắn nghiền nát xương?", "Linh cẩu", ["Chó sói", "Chó rừng", "Báo gấm"], "Linh cẩu có hàm răng và cơ hàm cực khỏe có thể nghiền nát cả những khúc xương to cứng nhất.", "8-9", 3, "MC", "Linh cẩu thảo nguyên"),
        ("Heo rừng", "Loài thú hoang họ lợn có cặp nanh nhọn hoắt chìa ra ngoài dùng để ủi đất và chiến đấu?", "Heo rừng", ["Lợn nhà", "Tê giác", "Hà mã"], "Heo rừng sống theo đàn trong rừng rậm, lớp lông cứng và da dày giúp chống gai cào xước.", "7-8", 2, "MC", "Heo rừng hung dữ"),

        # Đại dương & Sinh vật nước (DV071 - DV105)
        ("Cá voi xanh", "Loài động vật to lớn nhất từng tồn tại trên Trái Đất (lớn hơn cả khủng long khổng lồ) là loài nào?", "Cá voi xanh", ["Cá mập trắng", "Mực khổng lồ", "Khủng long bạo chúa"], "Cá voi xanh có thể dài tới 30 mét, nặng gần 200 tấn và tim của nó to bằng một chiếc ô tô nhỏ.", "6-7", 1, "MC", "Cá voi xanh khổng lồ"),
        ("Cá voi thở", "Cá voi là loài thú biển (động vật có vú) nên nó thở bằng cơ quan nào?", "Bằng Phổi (phải ngoi lên mặt nước thở)", ["Bằng Mang cá", "Bằng Da", "Bằng Đuôi"], "Cá voi không phải là cá, chúng đẻ con, cho con bú sữa mẹ và thở bằng phổi qua lỗ phun nước trên đỉnh đầu.", "7-8", 2, "MC", "Cá voi thở bằng phổi"),
        ("Cá heo", "Loài động vật biển thông minh, thân thiện, hay cứu người và giao tiếp bằng tiếng lách cách vui nhộn?", "Cá heo", ["Cá mập", "Bạch tuộc", "Hải mã"], "Cá heo có bộ não rất phát triển, có thể nhận biết chính mình trong gương và bơi lướt sóng tuyệt đẹp.", "6-7", 1, "MC", "Cá heo thân thiện"),
        ("Cá mập", "Loài săn mồi đại dương có bộ xương hoàn toàn bằng sụn, nhiều hàm răng sắc nhọn thay thế liên tục?", "Cá mập", ["Cá hồi", "Cá ngừ", "Cá heo"], "Cá mập có khứu giác cực nhạy có thể ngửi thấy một giọt máu loãng trong hàng triệu lít nước biển.", "7-8", 2, "MC", "Cá mập đại dương"),
        ("Cá ngựa", "Loài sinh vật biển kỳ lạ nào có hình dáng giống quân mã cờ vua và do con đực mang thai sinh con?", "Cá ngựa", ["Sao biển", "Cá đuối", "Lươn biển"], "Cá ngựa đực có túi ấp trước bụng, cá cái đẻ trứng vào túi để cá đực thụ tinh và mang thai sinh con.", "7-8", 2, "MC", "Cá ngựa mang thai"),
        ("Bạch tuộc", "Loài thân mềm có 8 chiếc tua dài mang giác bám, biết phun mực đen để trốn thoát kẻ thù là gì?", "Bạch tuộc", ["Mực ống", "Sứa biển", "Ốc sên"], "Bạch tuộc rất thông minh, có 3 trái tim, máu màu xanh lam và có thể biến đổi màu da ngụy trang tức thì.", "7-8", 2, "MC", "Bạch tuộc 8 xúc tua"),
        ("Mực ống", "Loài thân mềm biển có 10 xúc tua (8 tay ngắn và 2 tua dài) cùng chiếc mai nang bên trong là gì?", "Mực ống", ["Bạch tuộc", "Cua biển", "Nghêu"], "Mực bơi giật lùi bằng cách phụt luồng nước mạnh qua phễu nước, bơi rất nhanh khi gặp nguy hiểm.", "7-8", 2, "MC", "Mực ống bơi lùi"),
        ("Sứa biển", "Loài sinh vật biển thân mềm trong suốt hình chiếc dù bồng bềnh, tua mang tế bào châm gây ngứa bỏng?", "Sứa biển", ["Hải quỳ", "San hô", "Sao biển"], "Cơ thể sứa chứa hơn 95% là nước, một số loài sứa biển có chất độc có thể gây nguy hiểm cho người tắm biển.", "7-8", 2, "MC", "Sứa biển trong suốt"),
        ("Sao biển", "Loài động vật da gai hình ngôi sao 5 cánh dưới đáy biển có khả năng tái sinh mọc lại cánh bị đứt?", "Sao biển", ["Cầu gai", "Hải sâm", "Cua biển"], "Nếu một cánh sao biển bị cá cắn đứt, nó có thể tự mọc lại cánh mới hoàn chỉnh sau một thời gian.", "7-8", 2, "MC", "Sao biển 5 cánh"),
        ("Rùa biển", "Loài bò sát biển có mai cứng bơi lội bằng 4 chi hình mái chèo và bơi hàng ngàn dặm về bờ cát đẻ trứng?", "Rùa biển (Vích)", ["Cá sấu biển", "Ba ba", "Hải cẩu"], "Rùa biển cái luôn nhớ đường bơi về đúng bãi cát nơi mình sinh ra năm xưa để đào hố đẻ trứng.", "7-8", 2, "MC", "Rùa biển về bờ đẻ trứng"),
        ("Hải mã", "Loài thú biển vùng Bắc Cực băng giá có cặp răng nanh dài chĩa xuống dưới và ria mép dày rậm?", "Hải mã (Moóc)", ["Hải cẩu", "Sư tử biển", "Cá voi"], "Cặp nanh của hải mã dùng để tự vệ, chiến đấu tranh giành lãnh thổ và cắm vào băng giúp kéo cơ thể lên cạn.", "8-9", 3, "MC", "Hải mã Bắc Cực"),
        ("Hải cẩu", "Loài thú biển bơi lội thoăn thoắt dưới nước lạnh nhờ lớp mỡ dày và chi biến thành mái chèo?", "Hải cẩu", ["Gấu trắng", "Cá mập", "Rái cá"], "Hải cẩu có lớp mỡ dưới da dày giúp giữ ấm cơ thể trong làn nước đóng băng giá lạnh.", "7-8", 2, "MC", "Hải cẩu trượt băng"),
        ("San hô", "Những rạn san hô rực rỡ màu sắc dưới đáy biển là thực vật hay động vật?", "Là động vật (thuộc ngành ruột khoang)", ["Là thực vật biển", "Là các hòn đá ngầm vô tri", "Là một loại nấm"], "San hô thực chất là quần thể hàng triệu con polyp san hô bé nhỏ tiết ra canxi cacbonat tạo thành khung cứng.", "8-9", 3, "MC", "Rạn san hô rực rỡ"),
        ("Cá hề (Nemo)", "Loài cá nhỏ sặc sỡ màu cam sọc trắng sống an toàn giữa các xúc tua có độc của hải quỳ là gì?", "Cá hề (Clownfish)", ["Cá bảy màu", "Cá betta", "Cá chép"], "Cá hề có lớp chất nhầy đặc biệt trên da giúp nó không bị nọc độc của hải quỳ làm tổn thương.", "6-7", 1, "MC", "Cá hề sống cùng hải quỳ"),
        ("Cá đuối", "Loài cá biển có thân hình dẹt phẳng như cánh diều, bơi lượn uốn lượn nhịp nhàng và đuôi có gai nhọn?", "Cá đuối", ["Cá thờn bơn", "Cá chim", "Cá thu"], "Cá đuối có bộ xương bằng sụn, mắt ở mặt trên còn miệng và khe mang nằm ở mặt dưới bụng.", "7-8", 2, "MC", "Cá đuối cánh diều"),
        ("Cá chuồn", "Loài cá biển có vây ngực nở rộng như cánh chim, có thể phóng lên khỏi mặt nước và lướt trên không trung?", "Cá chuồn", ["Cá hồi", "Cá nục", "Cá trích"], "Cá chuồn bay lướt trên mặt nước hàng chục mét để thoát khỏi sự truy đuổi của cá săn mồi bên dưới.", "8-9", 3, "MC", "Cá chuồn bay lướt sóng"),
        ("Cá hồi", "Loài cá nào sinh ra ở sông suối nước ngọt, bơi ra biển lớn sinh sống rồi bơi ngược dòng về nguồn đẻ trứng?", "Cá hồi", ["Cá rô", "Cá tra", "Cá chim"], "Cá hồi vượt thác ghềnh ngoạn mục hàng ngàn km bơi ngược dòng nước chảy xiết để trở về nơi chôn rau cắt rốn đẻ trứng.", "8-9", 3, "MC", "Cá hồi vượt thác"),
        ("Cua biển", "Loài giáp xác có mai cứng, 8 cẳng 2 càng và thường bò ngang là con gì?", "Con Cua", ["Con Tôm", "Con Ghẹ", "Ốc mượn hồn"], "Cua bò ngang do cấu tạo các khớp chân của nó chỉ uốn cong được sang hai bên sườn.", "6-7", 1, "MC", "Cua bò ngang"),
        ("Tôm sú", "Loài giáp xác bơi giật lùi bằng cách cong đuôi gập mạnh về phía trước bụng là loài nào?", "Con Tôm", ["Con Cua", "Con Mực", "Con Ốc"], "Đuôi tôm có quạt đuôi khỏe giúp nó búng ngược về phía sau với tốc độ cực nhanh để trốn kẻ thù.", "6-7", 1, "MC", "Tôm búng đuôi"),
        ("Rái cá", "Loài thú nhỏ sống gần sông suối bơi lội giỏi, thích nằm ngửa trôi trên mặt nước và dùng đá đập vỡ vỏ sò?", "Rái cá", ["Chuột hương", "Hải ly", "Cầy mangut"], "Rái cá rất khéo tay, chúng đặt tảng đá lên ngực rồi cầm vỏ ốc sò đập mạnh vào đá để ăn thịt bên trong.", "7-8", 2, "MC", "Rái cá dùng công cụ"),
        ("Hải ly", "Loài gặm nhấm có răng cửa khỏe như rìu, chuyên đốn cây và xây đập ngăn suối làm tổ kiên cố?", "Hải ly (Beaver)", ["Rái cá", "Chuột chũi", "Sóc bay"], "Hải ly được mệnh danh là 'kỹ sư của tự nhiên', xây những con đập gỗ khổng lồ làm thay đổi cả hệ sinh thái.", "8-9", 3, "MC", "Hải ly xây đập gỗ"),

